-- Lua 5.1's runtime error messages (ldebug.c): the value an operation
-- failed on described as the local, global, field, upvalue or method it
-- came from, found by symbolic execution of the bytecode ("attempt to
-- index field 'b' (a nil value)"; were gopher-lua's "attempt to index a
-- non-table object(nil) with key 'c'", "cannot perform add operation
-- between nil and number", "__len undefined", "__unm undefined", "attempt
-- to call a non-function object", "attempt to compare table with table").
local function e(f, ...) local ok, m = pcall(f, ...) print(m) end
local x
local up = nil
local tt = {}
e(function() return x + 1 end)
e(function() local a; return a + 1 end)
e(function() local a = {}; return a.b.c end)
e(function() return y .. "s" end)
e(function() y = {} ; return y .. "s" end)
e(function() local t = {} ; return t.z.w end)
e(function() local t = {} ; t:m() end)
e(function() local t = {} ; t.f() end)
e(function() glob() end)
e(function() x() end)
e(function() local t = {} ; return t < t end)
e(function() return 1 < nil end)
e(function() return {} <= 1 end)
e(function() return #nil end)
e(function() return #x end)
e(function() return -{} end)
e(function() local s = {} return -s end)
e(function() for i = nil, 2 do end end)
e(function() for i = 1, nil do end end)
e(function() for i = 1, 2, {} do end end)
e(function() for i = "1", "2" do print(i) end end)
e(function() for k in nil do end end)
e(function() local t = {} ; return t.a .. "x" end)
e(function() local t = {a={}} ; return "x" .. t.a end)
e(function() local t = {a={}} ; return "x" .. t.a .. "y" end)
e(function() return '10' + 'text' end)
e(function() return '2' - nil end)
e(function() return 'hello' + 1 end)
e(function() local a = "x" return a .. {} end)
e(function() local a = {} return a .. "x" end)
e(function() local t = {} t.x.y = 1 end)
e(function() local t t.x = 1 end)
e(function() local t t[1] = 1 end)
e(function() return x[1] end)
e(function() return string.x.y end)
e((function() local u = x; return function() return u.a end end)())
e((function() local u = x; return function() return u + 1 end end)())
e((function() local u = x; return function() return u() end end)())
e(function() return math.foo() end)
e(function() return ("x"):nope() end)
e(function() return true < false end)
e(function() return "a" < 1 end)
e(function() local a, b = 1 ; return a + b end)
e(function() local a = 1 ; if a then a = nil end ; return a.x end)
e(function(...) local a, b = ... ; return a.x end)
e(function(...) return (...).x end)
e(function(...) return select(2, ...).x end)
e(function() local t = {} ; local x = t.a and t.b ; return x.y end)
e(function() local t = {} ; return (t.a or t.b).c end)
e(function() local t = {} ; return (t.a and t.b).c end)
e(function() return tt.a.b.c end)
e(function() return tt[1].x end)
e(function() local k = "z" ; return tt[k].x end)
e(function() return tt.x:y() end)
e(function() return tt:y() end)
e(function() return up:y() end)
e(function() return up.x end)
e(function() return string.nope.x end)
e(function() return #tt.a end)
e(function() return -tt.a end)
e(function() return tt.a .. tt.b end)
e(function() return "a" .. tt.b .. "c" end)
e(function() return 1 .. {} .. 2 end)
e(function() return tt.q + 1 end)
e(function() return 1 + tt.q end)
e(function() return tt.q * tt.r end)
e(function() return 2 ^ up end)
e(function() local x = up ; return x % 2 end)
e(function() local t = {f = 1} ; return t.f() end)
e(function() local t = {} ; return t.f(1, 2, 3) end)
e(function() return tt.g.h() end)
e(function() local f ; f() end)
e(function() local f = tt.zz ; f() end)
e(function() local a = {} ; a.b.c.d = 1 end)
e(function() up.x = 1 end)
e(function() up[1] = 1 end)
e(function() undefinedglobal.x = 1 end)
e(function() local t = setmetatable({}, {__index = 5}) ; return t.x end)
e(function() local t = setmetatable({}, {__newindex = 5}) ; t.x = 1 end)
e(function() for i = 1, 3 do local x = nil ; x.y = i end end)
e(function() for k, v in pairs({1}) do v.x = 1 end end)
e(function() for k, v in pairs({1}) do k() end end)
e(function() while true do local q ; q() end end)
e(function() repeat local q = up until q.x end)
e(function() local t = {} ; t.x = t.y.z end)
e(function() local a = up or nil ; return a.b end)
e(function() local a = not up ; return a.b end)
e(function() local a = up == nil ; return a.b end)
e(function() local a = (function() end)() ; return a.b end)
e(function() local a = {} ; return a[nil] end)
e(function() local a ; return a[1][2] end)
e(function() return ("x").y.z end)
e(function() return ("x"):rep(2):nope() end)
e(function() return math.huge.x end)
e(function() local s = "x" ; return s.y.z end)
e(function() local n = 0/0 ; return n.x end)
e(function() local n = 0/0 ; return n + {} end)
e(function() return {} + 0/0 end)
e(function() local t = {} return t.a + t.b end)
e(function() local t = {a = 1} return t.a + t.b end)
e(function() local t = {} return t < 1 end)
e(function() return print < print end)
e(function() return 1 <= "x" end)
e(function() return {} >= {} end)
e(function() local t = {} ; t.x.y = function() end end)
e(function() local f = function() end ; return f.x end)
e(function() local b = true ; return b() end)
e(function() local b = true ; return b:x() end)
e(function() return (nil)() end)
e(function() return (1)() end)
e(function() return ({})() end)
e(function() return tt.missing("x") end)
e(function() local t = {} ; return t.a.b, t.c end)
e(function() local x = 1 ; local function g() return x.y end ; return g() end)
e(function() local x = 1 ; local function g() x = nil return x.y end ; return g() end)
e(function() local t = { f = function(self) return self.x.y end } ; return t:f() end)
e(function() local u = up ; local function g() return function() return u.q end end ; return g()() end)
local co = coroutine.create(function() end)
e(function() return "a" < co end)
e(function() return co < "a" end)
e(function() return co.x end)
e(function() return #co end)
e(function() return co < co end)
-- __index and __newindex chains: the value the chain ends at isn't named
e(function() local t = setmetatable({}, {__index = setmetatable({}, {__index = 1})}) return t.x end)
e(function() return ("x").y.z end)
-- loops in __index chains
local loop = {}
setmetatable(loop, {__index = loop})
e(function() local t = setmetatable({}, {__index = setmetatable({}, getmetatable(loop))}) return loop.x end)
e(function() local t = setmetatable({}, {__newindex = loop}) setmetatable(loop, {__newindex = loop}) t.x = 1 end)
-- the partial results of a concatenation are in registers
local cc = setmetatable({}, {__concat = function() return {} end})
e(function() local s = "s" return s .. cc .. "x" end)
e(function() local s = {} return s .. "a" .. "b" end)
e(function() local a, b = "a", "b" return a .. b .. tt.q .. "c" end)
e(function() local a = "a" return a .. 1 .. true end)
-- method and field calls, in expressions and statements
e(function() return tt.f.g:h() end)
e(function() local s = "x" return s:upper():nope() end)
e(function() local t = {} t.x:y() end)
e(function() local t = {x = {}} t.x:y() end)
e(function() return tt[tt]() end)
e(function() return tt[1]() end)
e(function() local i = 1 return tt[i]() end)
-- vararg results, multiple assignments, nested closures
e(function(...) local a, b, c = ..., nil return c.x end, 1, 2)
e(function() local a, b = (function() return 1 end)() return b.x end)
e(function() local f = function() return up.x end return f() end)
e(function() local t = {} for i = 1, 2 do t = t[i] end end)
e(function() local t = {} while t do t = t.next.next end end)
e(function() local t = {1} for i, v in ipairs(t) do return v.x end end)
e(function() local a = 1 local b = a and nil return b.x end)
e(function() local t = {} local v = t.a or t.b return v.x end)
e(function() local t = {} return t.a.b.c.d end)
e(function() local t = {a = {b = {}}} return t.a.b.c.d end)
